-- AKUN ADMIN DEFAULT DATABASE (SAFE INSERT)
-- ============================================================
INSERT INTO "Users" ("username", "password", "role", "nama", "nik") 
SELECT 'adminrt', 'admin123', 'RT', 'Administrator RT', '0'
WHERE NOT EXISTS (SELECT 1 FROM "Users" WHERE "username" = 'adminrt');

-- ============================================================
-- OTOMATISASI PENGATURAN RLS & POLICY UNTUK ANONYMOUS KEY
-- ============================================================
DO $$
DECLARE
    t text;
BEGIN
    FOR t IN SELECT table_name FROM information_schema.tables WHERE table_schema = 'public' LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;', t);
        EXECUTE format('DROP POLICY IF EXISTS "Public Access Policy" ON public.%I;', t);
        EXECUTE format('CREATE POLICY "Public Access Policy" ON public.%I FOR ALL USING (true) WITH CHECK (true);', t);
    END LOOP;
END $$;

